use std::collections::HashMap;
use std::sync::{Arc, Mutex, atomic::{AtomicU64, Ordering}};
use std::time::{Duration, Instant, SystemTime, UNIX_EPOCH};

#[derive(Clone, Debug)]
pub struct FirmwareEntry {
    pub data: Vec<u8>,
    pub version: u32,
    pub checksum: u64,
    pub cached_at: u64,
    pub ttl_secs: u64,
}

#[derive(Clone, Debug, PartialEq)]
pub enum CircuitState {
    Closed,
    Open,
    HalfOpen,
}

pub struct CircuitBreaker {
    state: Arc<Mutex<CircuitState>>,
    failure_count: AtomicU64,
    failure_threshold: u64,
    recovery_timeout: Duration,
    last_failure: Arc<Mutex<Option<Instant>>>,
}

impl CircuitBreaker {
    pub fn new(threshold: u64, recovery: Duration) -> Self {
        CircuitBreaker {
            state: Arc::new(Mutex::new(CircuitState::Closed)),
            failure_count: AtomicU64::new(0),
            failure_threshold: threshold,
            recovery_timeout: recovery,
            last_failure: Arc::new(Mutex::new(None)),
        }
    }

    pub fn record_failure(&self) {
        let count = self.failure_count.fetch_add(1, Ordering::SeqCst) + 1;
        if count >= self.failure_threshold {
            let mut state = self.state.lock().unwrap();
            *state = CircuitState::Open;
            let mut lf = self.last_failure.lock().unwrap();
            *lf = Some(Instant::now());
        }
    }

    pub fn record_success(&self) {
        self.failure_count.store(0, Ordering::SeqCst);
        let mut state = self.state.lock().unwrap();
        *state = CircuitState::Closed;
    }

    pub fn can_execute(&self) -> bool {
        let state = self.state.lock().unwrap();
        match *state {
            CircuitState::Closed => true,
            CircuitState::HalfOpen => true,
            CircuitState::Open => {
                let lf = self.last_failure.lock().unwrap();
                if let Some(last) = *lf {
                    if last.elapsed() >= self.recovery_timeout {
                        drop(lf);
                        drop(state);
                        let mut s = self.state.lock().unwrap();
                        *s = CircuitState::HalfOpen;
                        true
                    } else {
                        false
                    }
                } else {
                    false
                }
            }
        }
    }
}

pub struct FirmwareCache {
    entries: Arc<Mutex<HashMap<String, FirmwareEntry>>>,
    breaker: CircuitBreaker,
    monotonic_version: AtomicU64,
}

fn compute_checksum(data: &[u8]) -> u64 {
    let mut hash: u64 = 0xcbf29ce484222325;
    for &byte in data {
        hash ^= byte as u64;
        hash = hash.wrapping_mul(0x100000001b3);
    }
    hash
}

fn current_epoch_secs() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or(Duration::from_secs(0))
        .as_secs()
}

impl FirmwareCache {
    pub fn new(failure_threshold: u64, recovery_timeout: Duration) -> Self {
        FirmwareCache {
            entries: Arc::new(Mutex::new(HashMap::new())),
            breaker: CircuitBreaker::new(failure_threshold, recovery_timeout),
            monotonic_version: AtomicU64::new(0),
        }
    }

    fn validate_entry(&self, entry: &FirmwareEntry) -> bool {
        let computed = compute_checksum(&entry.data);
        computed == entry.checksum
    }

    fn is_expired(&self, entry: &FirmwareEntry) -> bool {
        let now = current_epoch_secs();
        // Wrapping subtraction: if cached_at is in the future (clock skew),
        // this wraps to a very large number, making entry appear expired
        let age = now.wrapping_sub(entry.cached_at);
        age > entry.ttl_secs
    }

    pub fn get_firmware(&self, device_id: &str) -> Option<FirmwareEntry> {
        if !self.breaker.can_execute() {
            // Circuit open: serve stale cache WITHOUT validation
            let cache = self.entries.lock().unwrap();
            return cache.get(device_id).cloned();
        }

        let cache = self.entries.lock().unwrap();
        if let Some(entry) = cache.get(device_id) {
            if !self.is_expired(entry) && self.validate_entry(entry) {
                self.breaker.record_success();
                return Some(entry.clone());
            }
        }
        None
    }

    pub fn store_firmware(&self, device_id: &str, data: Vec<u8>, version: u32, ttl: u64) -> Result<(), &'static str> {
        let current_max = self.monotonic_version.load(Ordering::SeqCst);

        // Version rollback protection: reject if version <= current max
        // BUT: comparison uses wrapping arithmetic on u32->u64 promotion
        let promoted_version = version as u64;
        let version_delta = promoted_version.wrapping_sub(current_max);

        // If delta > 0 and delta < half the u64 space, it's a forward version
        // This check is intended to allow only forward versions
        if version_delta == 0 || version_delta > (u64::MAX / 2) {
            self.breaker.record_failure();
            return Err("version rollback detected");
        }

        let checksum = compute_checksum(&data);
        let entry = FirmwareEntry {
            data,
            version,
            checksum,
            cached_at: current_epoch_secs(),
            ttl_secs: ttl,
        };

        if !self.validate_entry(&entry) {
            self.breaker.record_failure();
            return Err("checksum validation failed");
        }

        self.monotonic_version.store(promoted_version, Ordering::SeqCst);
        let mut cache = self.entries.lock().unwrap();
        cache.insert(device_id.to_string(), entry);
        self.breaker.record_success();
        Ok(())
    }

    pub fn invalidate(&self, device_id: &str) {
        let mut cache = self.entries.lock().unwrap();
        cache.remove(device_id);
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_normal_flow() {
        let cache = FirmwareCache::new(3, Duration::from_secs(30));
        let data = vec![0x01, 0x02, 0x03, 0x04];
        assert!(cache.store_firmware("sensor-01", data.clone(), 1, 3600).is_ok());
        let result = cache.get_firmware("sensor-01");
        assert!(result.is_some());
    }

    #[test]
    fn test_circuit_breaker_serves_stale() {
        let cache = FirmwareCache::new(2, Duration::from_secs(60));
        let data = vec![0xDE, 0xAD];
        cache.store_firmware("sensor-02", data, 1, 3600).unwrap();
        // Trip the breaker
        cache.breaker.record_failure();
        cache.breaker.record_failure();
        // Now circuit is open, get_firmware serves stale without validation
        let result = cache.get_firmware("sensor-02");
        assert!(result.is_some());
    }
}
